from pathlib import Path
import json
root=Path(__file__).resolve().parents[3]
p=root/'tools/heart_sphere_methods_ru.md'
s=p.read_text(encoding='utf-8')
changes=json.loads(r'''[["Из этого допущения не следует известная доля крови.","Из этого допущения не следует, какова доля крови."],["при равномерном объёмном весе","при равномерном распределении веса по объёму"],["Общий центр; радиус по среднему квадрату расстояния","Общий центр; радиус по среднеквадратичному расстоянию до центра"],["Минимум площадочно-взвешенной ошибки расстояния","Минимум ошибки расстояния с весами по площади поверхности"],["Вертикальные черты обозначают объём.","Вертикальные черты в числителе и знаменателе обозначают объёмы соответствующих областей."],["Опорный кадр не называется конечной диастолой автоматически.","Опорному кадру нельзя автоматически присваивать статус конечной диастолы."],["Если вычислить центр зарегистрированной деформированной маски и точно перенести его обратно, получится исходный покадровый центр; такая операция сама по себе не создаёт нового метода по сравнению с Д1.","Если вычислить центр маски после жёсткой регистрации и перенести его обратно тем же преобразованием, получится исходный покадровый центр. Такая операция сама по себе не создаёт нового метода по сравнению с Д1."],["Динамику полости желудочка нельзя молча подставлять вместо динамики всего сердечного компартмента.","Динамику полости желудочка нельзя без явного указания использовать вместо динамики всего сердечного компартмента."],["Пятая геометрия — фактическая сегментированная область \\(H_t\\), содержащая все наблюдаемые различия формы.","Пятая геометрия — фактическая сегментированная область \\(H_t\\), содержащая все наблюдаемые различия относительно \\(H_0\\), включая перенос, изменение объёма и формы."],["Обозначим \\(T\\) перенос, \\(D\\) масштабирование, а \\(TD\\) их указанную композицию.","Обозначим \\(T\\) перенос, а \\(D\\) масштабирование относительно опорного центра \\(\\mathbf c_0\\). Композиция \\(TD=T\\circ D\\) означает сначала масштабирование, затем перенос."],["**Ошибка исходного импеданса** показывает соответствие базового состояния.","**Ошибка исходного импеданса** \\(e_0=Z(S_{t_0})-Z(H_{t_0})\\) показывает соответствие базового состояния и измеряется в Ом."],["ошибки производных по трём перемещениям и размеру","ошибки производных по трём координатам центра и радиусу"],["Продолжающаяся серия пространственного сравнения статических TEPC-моделей","Проводимая серия пространственных сравнений статических моделей сборок [40.09](40.09_Подготовка_чувствительности_сборок_TEPC.ipynb)"],["параметры сетки и преобразования в conversion manifest","параметры сетки и преобразования в манифесте conversion_manifest.json"],["Проверка перераспределения крови между камерами и многосферных вариантов","Анализ объёмов и геометрии камер; построение многосферных вариантов"],["Их расчёт по маскам станет новой производной следующего этапа.","Их расчёт по маскам станет новым производным результатом следующего этапа."],["В двух сериях принята предварительная возможность сопоставления циклов","Для двух серий предварительно разрешено сопоставление циклов"],["Выводы об анатомически достоверном движении и функциях сердца требуют принятого контроля сегментации.","Контроль анатомической точности сегментации необходим для достоверной анатомической и физиологической интерпретации. Его отсутствие ограничивает эту интерпретацию, но не блокирует условный вычислительный эксперимент."],["В описанной серии использованы четыре добровольца и по 20 реконструированных кадров сердечного цикла.","В описанной серии для каждого из четырёх добровольцев использовано по 20 реконструированных кадров сердечного цикла."],["при отношении токового и измерительного расстояний 2:1","при отношении расстояния между токовыми электродами к расстоянию между измерительными электродами 2:1"],["преимущество эллипсоида обсуждается для малых сборок, менее 140 мм","преимущество эллипсоида обсуждается для расстояний между токовыми электродами менее 140 мм"],["### 16.6. Что подтверждено историческим кодом","### 16.6. Какие операции подтверждаются просмотром исторического кода"],["для неё указаны мл на входе и мм на выходе","для неё указаны единицы: мл на входе и мм на выходе"],["не установлено данным аудитом","не установлено в рамках настоящего аудита"],["по импортированным поканальным смещениям","по импортированным смещениям по каналам"],["исторические функции следует переносить","исторические операции следует воспроизводить"],["конкретный алгоритм BOOK или иной алгоритм из источника","конкретный критерий и алгоритм источника"],["Амплитуды и направления движения следует сначала получить из проверенных текущих масок.","Амплитуды и направления движения следует сначала получить из текущих автоматических масок после зафиксированного технического контроля качества. До анатомической валидации это предварительные оценки геометрического движения."],["**Рисунок 4.","**Рисунок 4."]]''')
for a,b in changes:
    if a!=b and a not in s: raise ValueError('Missing replacement: '+a)
    s=s.replace(a,b)
p.write_text(s,encoding='utf-8',newline='\n')
g=root/'tools/build_heart_sphere_methods_report.py'
t=g.read_text(encoding='utf-8')
start=t.index('def _make_decomposition(')
